        }
    }

    return false;
}

    // Convert number to string and remove negative sign if present
    const str = Math.abs(num).toString();

    // Initialize counters
    let evenCount = 0;
    let oddCount = 0;

    // Iterate through each character in the string
    for (let digit of str) {
        const digitValue = parseInt(digit);
        if (digitValue % 2 === 0) {
            evenCount++;
        } else {
            oddCount++;
        }
    }

    // Return array with even and odd counts
    return [evenCount, oddCount];
}

    const romanNumerals = [
        [1000, 'm'],
        [900, 'cm'],
        [500, 'd'],
        [400, 'cd'],
        [100, 'c'],
        [90, 'xc'],
        [50, 'l'],
        [40, 'xl'],
        [10, 'x'],
        [9, 'ix'],
        [5, 'v'],
        [4, 'iv'],
        [1, 'i']
    ];

    let result = '';

    for (let i = 0; i < romanNumerals.length; i++) {
        const value = romanNumerals[i][0];
        const numeral = romanNumerals[i][1];

        // Calculate how many times this numeral should be used
        const count = Math.floor(number / value);

        // Add the corresponding roman numeral count times
        for (let j = 0; j < count; j++) {
            result += numeral;
        }

        // Update the remaining number
        number %= value;

        // If we've processed all numerals, break
        if (number === 0) break;
    }

    return result;
}

    // Sort the sides to identify the longest side (potential hypotenuse)
    const sides = [a, b, c].sort((x, y) => x - y);
    const hypotenuse = sides[2];
    const opposite = sides[1];
    const adjacent = sides[0];

    // Check if the Pythagorean theorem holds: a² + b² = c²
    // where c is the hypotenuse
    return Math.pow(opposite, 2) + Math.pow(adjacent, 2) === Math.pow(hypotenuse, 2);
}

    // Helper function to count unique characters in a word
    function countUniqueChars(word) {
        const charSet = new Set();
        for (const char of word) {
            charSet.add(char);
        }
        return charSet.size;
    }

    // Find the maximum number of unique characters among all words
    const maxUnique = words.reduce((max, word) => {
        return countUniqueChars(word) > countUniqueChars(max) ? countUniqueChars(word) : countUniqueChars(max);
    }, words[0]);

    // Find all words that have the maximum number of unique characters
    const candidates = words.filter(word => countUniqueChars(word) === maxUnique);

    // Return the lexicographically first candidate
    return candidates.sort().join('');
}

    // Calculate how many carrots you will eat in total (current + needed)
    const totalEaten = number + need;

    // Determine how many carrots you can actually eat from the remaining stock
    const carrotsToEat = Math.min(remaining, totalEaten);

    // Calculate the final amount of carrots eaten (current + what you actually ate)
    const finalEaten = number + carrotsToEat;

    // Calculate the remaining carrots after your meals
    const finalRemaining = remaining - carrotsToEat;

    return [finalEaten, finalRemaining];
}

    let result = operand[0];

    for (let i = 0; i < operator.length; i++) {
        const op = operator[i];
        const nextOperand = operand[i + 1];

        switch (op) {
            case '+':
                result += nextOperand;
                break;
            case '-':
                result -= nextOperand;
                break;
            case '*':
                result *= nextOperand;
                break;
            case '//':
                result = Math.floor(result / nextOperand);
                break;
            case '**':
                result = result ** nextOperand;
                break;
            default:
                throw new Error(`Unknown operator: ${op}`);
        }
    }

    return result;
}

    // Check if the string contains any letters
    const hasLetters = /[a-zA-Z]/.test(s);

    if (!hasLetters) {
        // If no letters, reverse the string
        return s.split('').reverse().join('');
    } else {
        // If letters exist, reverse the case of each character
        return s.split('').map(char => {
            if (char >= 'a' && char <= 'z') {
                return char.toUpperCase();
            } else if (char >= 'A' && char <= 'Z') {
                return char.toLowerCase();
            } else {
                return char;
            }
        }).join('');
    }
}

    if (!text || text === "") {
        return undefined;
    }

    // Using CryptoJS to generate MD5 hash
    const CryptoJS = require('crypto-js');
    return CryptoJS.SHA256(text).toString(CryptoJS.enc.Hex);
}

    // Ensure we're working with the smaller range
    const start = Math.min(a, b);
    const end = Math.max(a, b);

    // Array to store even digits
    const result = [];

    // Iterate through the range and collect even digits
    for (let num = start; num <= end; num++) {
        // Check if the number is even
        if (num % 2 === 0) {
            // Extract each digit and check if it's even
            let temp = num;
            while (temp > 0) {
                let digit = temp % 10;
                if (digit % 2 === 0) {
                    result.push(digit);
                }
                temp = Math.floor(temp / 10);
            }
        }
    }

    // Remove duplicates and sort in ascending order
    const uniqueDigits = [...new Set(result)];
    return uniqueDigits.sort((a, b) => a - b);
}
